import json
import sys
import operator

def evaluate_formula(row, formula):
    try:
        # Replace field names with their values in the row
        for field in formula.split():
            if field in row:
                row[field] = str(row[field])
        # Evaluate the arithmetic expression
        return eval(formula)
    except (SyntaxError, ZeroDivisionError, NameError, TypeError):
        return None

def process_json_input():
    try:
        data = json.load(sys.stdin)
        if 'rows' not in data or 'formulas' not in data:
            return None

        rows = data['rows']
        formulas = data['formulas']
        formula_keys = list(formulas.keys())

        for row in rows:
            for key in formula_keys:
                formula = formulas[key]
                result = evaluate_formula(row, formula)
                if result is None:
                    return None
                row[key] = result

        return json.dumps(rows)
    except json.JSONDecodeError:
        return None

if __name__ == "__main__":
    output = process_json_input()
    if output is not None:
        sys.stdout.write(output + "\n")
    else:
        sys.exit(1)
